git checkout -b deploy/fly-io && mkdir -p deploy .github/workflows

cat > astro.config.mjs <<'EOF'
// @ts-check
import { defineConfig } from "astro/config";

import preact from "@astrojs/preact";

// https://astro.build/config
export default defineConfig({
  // The public URL of the site. Used for absolute links such as those in the RSS feed.
  // Set SITE_URL at build time (see fly.toml [build.args]) to your custom domain.
  site: process.env.SITE_URL || "https://example.com",
  integrations: [preact()],
});
EOF

cat > src/pages/404.astro <<'EOF'
---
import BaseLayout from "../layouts/BaseLayout.astro";
const pageTitle = "Page not found";
---

<BaseLayout pageTitle={pageTitle}>
  <p>Sorry, that page doesn't exist. <a href="/">Go back home</a>.</p>
</BaseLayout>
EOF

cat > .dockerignore <<'EOF'
node_modules
dist
.astro
.git
.github
.vscode
.idea
.env
.env.*
*.log
.DS_Store
EOF

cat > Dockerfile <<'EOF'
# syntax=docker/dockerfile:1

# ---- Build stage: compile the Astro site to static files ----
FROM node:22-bookworm-slim AS build
WORKDIR /app

COPY package.json package-lock.json ./
RUN npm ci --no-audit --no-fund

COPY . .

# Public URL of the site (used for absolute URLs, e.g. in rss.xml).
ARG SITE_URL=https://example.com
ENV SITE_URL=${SITE_URL}
RUN npm run build

# ---- Runtime stage: serve the static files with nginx (runs as non-root on :8080) ----
FROM nginxinc/nginx-unprivileged:stable-alpine

COPY deploy/nginx.conf /etc/nginx/conf.d/default.conf
COPY --from=build /app/dist /usr/share/nginx/html

EXPOSE 8080
# The base image's default CMD runs nginx in the foreground; access and error
# logs go to stdout/stderr, which Fly collects (`fly logs`).
EOF

cat > deploy/nginx.conf <<'EOF'
# Included inside the `http {}` block of the nginx-unprivileged base image.

# Fly's edge proxy terminates TLS and sets Fly-Client-IP to the real visitor IP.
log_format fly '$http_fly_client_ip "$request" $status $body_bytes_sent '
               '$request_time "$http_referer" "$http_user_agent"';

server {
    listen 8080;
    listen [::]:8080;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;

    access_log /dev/stdout fly;
    error_log  /dev/stderr warn;

    server_tokens off;

    # TLS is terminated at Fly's proxy, so nginx only sees plain HTTP on :8080.
    # Emit relative redirects so they never point at http://<host>:8080/.
    absolute_redirect off;

    gzip on;
    gzip_vary on;
    gzip_min_length 512;
    gzip_types text/css application/javascript application/json
               application/xml application/rss+xml image/svg+xml text/plain;

    # Security headers (inherited by every location below that doesn't call add_header).
    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;

    # HTML, RSS, etc.: always revalidate so a new deploy is visible immediately.
    expires epoch;

    # Health check used by Fly (see fly.toml). Kept out of the access log.
    location = /healthz {
        access_log off;
        default_type text/plain;
        return 200 "ok\n";
    }

    # Astro's hashed build assets never change, so cache them for a long time.
    location /_astro/ {
        expires max;
        try_files $uri =404;
    }

    location / {
        # Astro emits /blog/index.html; site links use both /blog and /blog/.
        # Serve the page directly instead of redirecting.
        try_files $uri $uri/index.html $uri.html =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF
echo ok
